  border-bottom: 1px solid var(--rule);
}

.pageHeader {
  min-height: 58vh;
  display: grid;
  align-content: end;
}

.pageHeader h1,
.hero h1 {
  max-width: 12ch;
  margin: var(--space-3, 12px) 0 0;
  font-family: var(--serif);
  font-size: clamp(64px, 9vw, 132px);
  font-weight: 400;
  letter-spacing: -0.05em;
  line-height: 0.86;
}

.eyebrow {
  margin: 0 0 var(--space-4, 16px);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.dek {
  max-width: 48ch;
  margin: var(--space-5, 24px) 0 0;
  color: var(--ink-60);
  font-size: clamp(17px, 2vw, 21px);
  line-height: 1.6;
}

.block[data-theme='dark'],
.block[data-theme='ink'] {
  background: var(--ink);
  color: var(--paper);
}

.block[data-theme='dark'] .dek,
.block[data-theme='ink'] .dek {
  color: var(--ink-20);
}

.block[data-theme='paper-2'],
.block[data-theme='stone'] {
  background: var(--paper-2);
}

.hero {
  min-height: 82vh;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(320px, 0.95fr);
  gap: var(--component-gap, 32px);
  align-items: center;
}

.heroCopy {
  position: relative;
  z-index: 1;
}

.heroImage {
  position: relative;
  min-height: 62vh;
  overflow: hidden;
  background: var(--paper-2);
}

.heroImage img,
.mediaImage img,
.cardImage img {
  object-fit: cover;
}

.hero[data-variant='cover'] {
  position: relative;
  min-height: 92vh;
  display: grid;
  grid-template-columns: 1fr;
  align-items: end;
  overflow: hidden;
  color: var(--paper);
}

.hero[data-variant='cover'] .heroCopy {
  max-width: 820px;
}

.hero[data-variant='cover'] .heroImage {
  position: absolute;
  inset: 0;
  min-height: 0;
}

.hero[data-variant='cover'] .heroImage::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgb(24 25 24 / 78%), rgb(24 25 24 / 12%));
  content: '';
}

.hero[data-variant='minimal'] {
  min-height: 62vh;
  grid-template-columns: 1fr;
}

.hero[data-variant='minimal'] .heroImage {
  display: none;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3, 12px);
  margin-top: var(--space-6, 32px);
}

.primaryAction,
.secondaryAction {
  padding: var(--space-4, 16px) var(--space-5, 24px);
  border: 1px solid currentColor;
  color: inherit;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-decoration: none;
  text-transform: uppercase;
}

.primaryAction {
  background: var(--ink);
  color: var(--paper);
}

.block[data-theme='dark'] .primaryAction,
.block[data-theme='ink'] .primaryAction {
